CREATE VIRTUAL TABLE t1 USING fts3(content); WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<31) INSERT INTO t1(rowid,content) SELECT x, trim((CASE WHEN (x & 1)<>0 THEN 'one ' ELSE '' END)||(CASE WHEN (x & 2)<>0 THEN 'two ' ELSE '' END)||(CASE WHEN (x & 4)<>0 THEN 'three ' ELSE '' END)||(CASE WHEN (x & 8)<>0 THEN 'four ' ELSE '' END)||(CASE WHEN (x & 16)<>0 THEN 'five ' ELSE '' END)) FROM c; INSERT INTO t1(content) VALUES(NULL);